alter table public.external_ingestion_adapters drop constraint external_ingestion_adapters_adapter_kind_check; alter table public.external_ingestion_adapters add constraint external_ingestion_adapters_adapter_kind_check check (adapter_kind = any(array['socrata'::text,'arcgis'::text,'geojson'::text,'bulk'::text,'fused_overture'::text])); insert into public.external_ingestion_adapters(source_key,adapter_kind,endpoint_url,enabled,page_size,cursor_offset,refresh_interval_minutes,next_run_at,field_map,static_metadata) values ('overture_places','fused_overture','https://www.fused.io/server/v1/realtime-shared/UDF_Overture_Maps_Example/run/tiles/{z}/{x}/{y}?dtype_out_vector=geojson&overture_type=place',true,1,0,10080,now(),'{}'::jsonb,jsonb_build_object('provider','Overture Maps via Fused','dataset','Overture Places','publisher','Overture Maps Foundation','corridor','kc_to_chicago','zoom',12,'exclude_geographic_entities',true)) on conflict(source_key) do update set adapter_kind=excluded.adapter_kind,endpoint_url=excluded.endpoint_url,enabled=true,page_size=1,refresh_interval_minutes=excluded.refresh_interval_minutes,next_run_at=now(),field_map=excluded.field_map,static_metadata=excluded.static_metadata,updated_at=now();
